# *****************************************************************************
# Parameters for mofa_factors_interpretation.R
#
# Edit the values below for the study/run being analyzed. This file must be
# located in the same directory as mofa_factors_interpretation.R.
# *****************************************************************************

# Full path to the MOFA results file generated by mofa_analysis.R.
# This is typically the model.hdf5 file saved by the MOFA analysis workflow.
mofa_res_fname <- file.path("D:/R_sessions/PROSPR/MOFA/old runs",
		"2026_Jun_29_12_02_13_visit=24mo_change_scores_ungrouped_views=pr+mb",
		"model.hdf5")
		

# Full path to the Metabolon annotation CSV file used to annotate metabolomics
# features. Set this to NULL only when the MOFA results object does not contain
# a view named "metabolomics".
metab_ann_fn <- file.path("E:/Data/PROSPR-FAST/CALERIE/metabolomics",
		"metabolon_annotations.csv")

# Parent directory in which the mofa_factor_interpretation results directory
# will be created. If NULL, the results directory is created alongside the MOFA
# results file specified by mofa_res_fname.
output_dir <- NULL

# MOFA views to analyze. Use "all" to analyze every supported view present in
# the MOFA results object, or provide a character vector containing any subset
# of: "proteomics", "methylation", "metabolomics", and "expression".
views <- "all"

# MOFA factors to analyze. Use "all" to analyze every factor, or specify the
# factor selection accepted by MOFA2::get_weights(), e.g. "Factor10".
factors <- "Factor10"

# Rule used to select high-loading features for outputs and metabolomics ORA.
# Supported values are "top_n", "zscore", and "quantile".
selection_mode <- "top_n"

# Number of positive and negative features selected per factor/view when
# selection_mode = "top_n". This setting is ignored for the other selection
# modes.
top_n <- 100

# Absolute loading z-score threshold used when selection_mode = "zscore".
# Features with an absolute z-score at least this large are selected. This
# setting is ignored for the other selection modes.
z_cutoff <- 2.5

# Absolute-loading quantile used when selection_mode = "quantile". For example,
# 0.95 selects features whose absolute loading is at or above the 95th percentile
# within the corresponding factor/view. This setting is ignored for the other
# selection modes.
quantile_cutoff <- 0.95

# One or more Gene Ontology namespaces to analyze with fgsea for proteomics,
# expression, and methylation views. Supported values are "BP", "MF", and "CC".
# Each ontology is analyzed separately and the results are then combined.
go_ontology <- c("BP", "MF")

# Maximum adjusted p-value retained in the enrichment results. This threshold is
# applied to both fgsea and metabolomics ORA results.
qvalue_cutoff <- 0.10

# Adjusted p-value threshold used for enrichment terms included in the PDF report
# and in the factor-level interpretation text.
report_significance_cutoff <- 0.05

# Whether to generate the PDF factor-interpretation report.
render_report <- TRUE

# Number of task-level parallel workers used for enrichment analysis. Set to 1
# for serial execution. On Windows, values greater than 1 require the future and
# future.apply packages. Increase this according to the CPUs available on the
# execution system; using too many workers can reduce performance.
n_cores <- 1L
